body {
  margin:0;
  height:100vh;
  background:#000;
  color:#fff;
  display:flex;
  justify-content:center;
  align-items:center;
  font-family:sans-serif;
  overflow:hidden;
}

h1 {
  font-size:3rem;
  z-index:1;
}

.stars {
  position:absolute;
  width:100%;
  height:100%;
  top:0;
  left:0;
  pointer-events:none;
}

.star {
  position:absolute;
  width:20px;
  height:20px;
  color:#fff;
  font-size:20px;
  line-height:1;
  text-align:center;
  animation:twinkle 2s infinite;
}

.star:nth-child(1){animation-delay:0s;}
.star:nth-child(2){animation-delay:0.5s;}
.star:nth-child(3){animation-delay:1s;}
.star:nth-child(4){animation-delay:1.5s;}
.star:nth-child(5){animation-delay:2s;}

@keyframes twinkle{
  0%, 100%{opacity:0.2;}
  50%{opacity:1;}
}

.star::before{
  content:"★";
}
